// FILE_REF: ./nodes/format_whatsapp_template.js
const req = $('Update Request Status DB').first().json;
const parent = $input.all()[0]?.json;
const status = req.status;
const studentName = parent.student_name;
const rollNo = parent.roll_no;
const requestType = req.request_type;
const startDate = req.start_date;
const endDate = req.end_date;
const advisorNotes = req.advisor_notes || 'None';
const parentPhone = parent.parent_phone_number;

let messageText = '';
if (status === 'Approved') {
  messageText = `✅ OFFICIAL INSTITUTION NOTICE: The ${requestType} request for ${studentName} (${rollNo}) from ${startDate} to ${endDate} has been APPROVED by the Class Advisor.\nRemarks: "${advisorNotes}".`;
} else {
  messageText = `❌ OFFICIAL INSTITUTION NOTICE: The ${requestType} request for ${studentName} (${rollNo}) from ${startDate} to ${endDate} has been REJECTED by the Class Advisor.\nRemarks: "${advisorNotes}".`;
}

return [{ json: { to: parentPhone, body: messageText, requestId: req.request_id, status } }];
